import { ChangeDetectorRef, Component } from '@angular/core';
import { DatepickerComponent } from '../../../../shared/components/datepicker/datepicker.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { DatePipe, NgClass } from '@angular/common';
// import { LogtableComponent } from '../../../../realtime/components/logtable/logtable.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { RealtimeactivityService } from '../../../services/realtimeactivity/realtimeactivity.service';
import { ActivatedRoute } from '@angular/router';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-realtimeactivity',
  standalone: true,
  imports: [IconComponent, NgClass, MatTooltipModule, DatePipe],
  templateUrl: './realtimeactivity.component.html',
  styleUrl: './realtimeactivity.component.scss'
})
export class RealtimeactivityComponent {



  nCaseid: string= null;

  sessionList = [];

  currentSession: any;

  constructor(private realtieactivityService: RealtimeactivityService, private route: ActivatedRoute, private cdr: ChangeDetectorRef, private userPermissions: UserPermissionService) {
    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;
    userPermissions.userPermissionList(this.nCaseid);
  }




  back() {
    window.history.back();
  }

  async ExportData() {

  }


  ngOnInit() {
    this.getsessionsbycaseid()
  }


  async uploadComplete() {

    // obj.isUploaded = true;
    // obj.isTranscript = false;
    // const nUserid = window.localStorage.getItem('nUserid') ? (window.localStorage.getItem('nUserid')) : 0;
    // await this.sessionS.transsciptUpdate(obj.nSesid, nUserid, this.current_case.nCaseid, 'C', obj.cProtocol);
    this.currentSession['isUploaded'] = true;
    this.currentSession['isTranscript'] = false;

    const obj = {
      nSesid: this.currentSession['nSesid'],
      nCaseid: this.nCaseid,
      cProtocol: this.currentSession['cProtocol'],
      cFlag: 'C'
    }
    const data = await this.realtieactivityService.transsciptUpdate(obj);

    if (data.msg == 1) {
      this.getsessionsbycaseid()
    }
    this.cdr.detectChanges();

  }


  async publishComplete(x) {

    delete x['cUploadstatus'];
    const obj = {
      nSesid: x.nSesid,
      nCaseid: this.nCaseid,
      cProtocol: x.cProtocol,
      cFlag: 'P'
    }
    const res = await this.realtieactivityService.transsciptUpdate(obj);

    if (res.msg == 1) {
      x['isUploaded'] = true;
      x['isTranscript'] = true;
    }
    // x.isUploaded = true;
    // x.isTranscript = true;
    // await this.realtieactivityService.transcriptSync({ nCaseid: this.nCaseid, nSesid: obj.nSesid });

    this.getsessionsbycaseid();
    this.cdr.detectChanges();
  }




  updateIds(x) {
    // this.isReplace = false;
    // this.current_case = x;
    // this.store.nCaseid = x.nCaseid;
    // this.store.nSectionid = x.nSectionid;
    this.currentSession = x;
    document.getElementById('uploadFile').click()
    this.cdr.detectChanges();
  }

  async onFileChange(e) {
    if (!e.target.files[0]) return;
    const formData = new FormData();
    const filename = `s_${this.currentSession?.nSesid}`
    formData.append('filename', filename);
    formData.append('caseid', this.nCaseid.toString());
    formData.append('file', e.target.files[0]);


    this.currentSession.cUploadstatus = 'U';

    const res = await this.realtieactivityService.upload(formData);
    if (res == -1) {
      this.currentSession.cUploadstatus = 'F';
    }
    else {
      this.currentSession.cUploadstatus = 'C';
      this.currentSession.nProgress = 100;
      this.uploadComplete()
    }
    this.cdr.detectChanges();
  }



  async getsessionsbycaseid() {
    const res = await this.realtieactivityService.getsessionsbycaseid(this.nCaseid)
    if (res && res.length) {
      this.sessionList = res;
    }
    this.cdr.detectChanges();
  }
}
